mapper.select:
SELECT member.memberid, member.membername, vocatest.id, vocatest.memodate, vocatest.vocalevel, (SELECT codename FROM cmm_code WHERE code = vocatest.vocalevel AND codetype = 'VOCALEVEL') vocalevel_name, vocatest.vocano, vocatest.targetcount, vocatest.lastyn, vocatest.examflag, IFNULL((SELECT MAX(ve.degree) FROM ttokssaemdb.vocaexam ve WHERE ve.memberid = vocatest.memberid AND ve.memodate = vocatest.memodate), 0) degree, IFNULL((SELECT total FROM ttokssaemdb.vocaexam WHERE memodate = vocatest.memodate AND memberid = vocatest.memberid ORDER BY degree DESC LIMIT 1), 0) total, IFNULL((SELECT wrong FROM ttokssaemdb.vocaexam WHERE memodate = vocatest.memodate AND memberid = vocatest.memberid ORDER BY degree DESC LIMIT 1), 0) wrong FROM ttokssaemdb.member member, ttokssaemdb.checkvocaplan vocatest
AND member.memberid = vocatest.memberid AND vocatest.examflag <> 'D'
AND member.branchid = #{branchid}
AND ( member.membername LIKE #{likeQuery} )
vocatest.id vocatest.vocalevel vocatest.vocalevel vocatest.vocano vocatest.memodate vocatest.lastyn member.membername DESC ASC DESC
LIMIT ${length} OFFSET ${start}

mapper.delete:
DELETE FROM ttokssaemdb.vocaexam
WHERE
  memberid = #{memberid}
  AND memodate = #{memodate}
